/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		params: {
			selectedTabIndex: event.payload.selectedTabIndex + ''
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	if (!event.payload || event.payload.type != 'NOW_VIS_WRAPPER#CLICKED') {
        return;
    }

	return {
		propName: 'selectedBaseAggQuery',
		value: event?.payload?.payload?.params?.query
	};
}

